# Let me try using a backtracking search with constraint propagation
import random

def solve_magic_square():
    n = 6
    magic_sum = 111
    grid = [0] * 36
    used = set()

    # Pre-compute which cells belong to which constraints
    rows = [[i*6+j for j in range(6)] for i in range(6)]
    cols = [[i*6+j for i in range(6)] for j in range(6)]
    diag1 = [i*6+i for i in range(6)]
    diag2 = [i*6+(5-i) for i in range(6)]

    all_constraints = rows + cols + [diag1, diag2]

    # For each cell, which constraints does it belong to?
    cell_constraints = [[] for _ in range(36)]
    for ci, constraint in enumerate(all_constraints):
        for cell in constraint:
            cell_constraints[cell].append(ci)

    def get_constraint_sum(constraint_idx):
        return sum(grid[cell] for cell in all_constraints[constraint_idx] if grid[cell] != 0)

    def get_constraint_filled(constraint_idx):
        return sum(1 for cell in all_constraints[constraint_idx] if grid[cell] != 0)

    def get_constraint_empty(constraint_idx):
        return sum(1 for cell in all_constraints[constraint_idx] if grid[cell] == 0)

    def is_valid(cell, value):
        if value in used:
            return False
        for ci in cell_constraints[cell]:
            current_sum = get_constraint_sum(ci)
            filled = get_constraint_filled(ci)
            empty = get_constraint_empty(ci)
            if current_sum + value > magic_sum:
                return False
            if current_sum + value + empty * 36 < magic_sum:
                return False
            if current_sum + value + empty * 1 > magic_sum:
                return False
            # If this fills the constraint, check exact sum
            if filled + 1 == 6:
                if current_sum + value != magic_sum:
                    return False
        return True

    def solve(pos=0):
        if pos == 36:
            return True

        if grid[pos] != 0:
            return solve(pos + 1)

        # Try values in random order for variety
        values = list(range(1, 37))
        random.shuffle(values)

        for v in values:
            if is_valid(pos, v):
                grid[pos] = v
                used.add(v)
                if solve(pos + 1):
                    return True
                grid[pos] = 0
                used.remove(v)

        return False

    if solve():
        return grid
    return None

# Try multiple times with different random seeds
for seed in range(10):
    random.seed(seed)
    result = solve_magic_square()
    if result:
        print(f"Found solution with seed {seed}")
        sq = [result[i*6:(i+1)*6] for i in range(6)]
        for row in sq:
            print(row)
        print(f"\nRow sums: {[sum(row) for row in sq]}")
        print(f"Col sums: {[sum(sq[i][j] for i in range(6)) for j in range(6)]}")
        print(f"Main diag: {sum(sq[i][i] for i in range(6))}")
        print(f"Anti diag: {sum(sq[i][5-i] for i in range(6))}")
        print(f"Flat: {result}")
        break
    else:
        print(f"No solution with seed {seed}")
